      { supplier: "Swiss Precision", price: 1100,   currency: "CHF" },
      { supplier: "Japan Direct",    price: 180000, currency: "JPY" }
    ]
  }
}];

// BEREITS FERTIG – nicht verändern
const r = $input.first().json;
const pflicht = ['cheapest_offer_supplier', 'cheapest_offer_price_EUR', 'timestamp'];
const fehlt = pflicht.filter(k => r[k] === undefined || r[k] === null || r[k] === '');
if (fehlt.length) {
  const tipp = fehlt.map(k => {
    const aehnlich = Object.keys(r).find(x => x.toLowerCase() === k.toLowerCase());
    return aehnlich ? `'${k}' (vorhanden ist '${aehnlich}', Groß-/Kleinschreibung zählt!)` : `'${k}'`;
  }).join(', ');
  throw new Error(`Diese Felder fehlen oder sind leer: ${tipp}. Aufgabe 5 (Edit Fields) prüfen. Sind sie dort leer, liefert Aufgabe 4 kein 'cheapestOffer'.`);
}
const hinweise = [];
const teilnehmer = String($('AUFGABE 0 – Namen eintragen').first().json.name || '').trim();
if (!teilnehmer) hinweise.push('AUFGABE 0: Euer Name fehlt. Tragt ihn im ersten Node ein, sonst landet nichts im Scoreboard.');
if (typeof r.cheapest_offer_price_EUR !== 'number') hinweise.push("'cheapest_offer_price_EUR' ist kein Number. Im Edit-Fields-Node den Typ auf Number stellen.");
if (!(Number(r.cheapest_offer_price_EUR) > 0)) hinweise.push("Der Preis ist 0. Liefert der HTTP Request 'rates.EUR'? Stimmt der Node-Name in $('Loop Over Items')?");
const lieferanten = ['TechSupply US', 'Nordic Parts', 'UK Components', 'Swiss Precision', 'Japan Direct'];
if (!lieferanten.includes(r.cheapest_offer_supplier)) hinweise.push(`Lieferant '${r.cheapest_offer_supplier}' ist unbekannt. Kommt 'cheapest_offer_supplier' aus Aufgabe 4?`);
return [{ json: { ...r, korrekt: hinweise.length === 0 ? '✅ Ja' : '❌ Nein', hinweise: hinweise.length ? hinweise.join(' | ') : 'Alles richtig!' } }];

// Spielwiese: drei Angebote
return [
  { json: { supplier: 'A', price: 100 } },
  { json: { supplier: 'B', price: 200 } },
  { json: { supplier: 'C', price: 300 } }
];
